cypress_script:
describe('Progress Bar Functionality', () => {
  it('should start the progress bar', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    // Assert that the button text changes to 'Stop'
    cy.get('#startStopButton').should('have.text', 'Stop');
  });

  it('should not change URL when clicking start/stop', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.url().should('eq', 'https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.url().should('eq', 'https://demoqa.com/progress-bar');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Progress Bar Functionality', () => {
  test('should start the progress bar', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    // Assert that the button text changes to 'Stop'
    const buttonText = await page.textContent('#startStopButton');
    expect(buttonText).toBe('Stop');
  });

  test('should not change URL when clicking start/stop', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    await page.click('#startStopButton');
    expect(page.url()).toBe('https://demoqa.com/progress-bar');
  });
});
